struct Order {
    let id: OrderID
    let customer: CustomerID
    let lines: [Line]

    init(customer: CustomerID, lines: [Line]) throws {
        guard !lines.isEmpty else { throw OrderError.empty }
        self.id = OrderID()          // identity is minted inside the factory
        self.customer = customer
        self.lines = lines
    }
}
